const YAQEEN_IMAGE_CACHE='yaqeen-images-v1';
function warmImageCache(urls:(string|null|undefined)[]){
 if(typeof window==='undefined'||!('caches' in window))return;
 const unique=[...new Set(urls.filter((u):u is string=>Boolean(u&&/^https:\/\//.test(u))))];
 if(!unique.length)return;
 void caches.open(YAQEEN_IMAGE_CACHE).then(cache=>Promise.allSettled(unique.map(async url=>{
  if(await cache.match(url))return;
  const response=await fetch(url,{mode:'cors',credentials:'omit',cache:'force-cache'});
  if(response.ok)await cache.put(url,response.clone());
 }))).catch(()=>{});
}
