const PUBLIC_ORIGIN='https://shereenakoum.github.io';
const PUBLIC_BASE='/YaqeenShop';
function SeoMetadata(){const loc=useLocation();useEffect(()=>{if(loc.pathname.startsWith('/admin')||loc.pathname==='/login')return;const path=loc.pathname||'/';const labels:Record<string,[string,string]>={'/':['YAQEEN — A more meaningful life','Thoughtful Islamic acrylic reminders designed to bring faith, meaning and intention into everyday life.'],'/shop':['Shop meaningful Islamic reminders | YAQEEN','Explore YAQEEN’s collection of thoughtful Islamic acrylic reminders and meaningful gifts.'],'/cart':['Your bag | YAQEEN','Review the meaningful reminders in your YAQEEN shopping bag.'],'/checkout':['Secure checkout | YAQEEN','Complete your YAQEEN order securely and provide your delivery details.'],'/order-confirmation':['Order confirmation | YAQEEN','Your YAQEEN order confirmation and next steps.'],'/search':['Search the collection | YAQEEN','Search YAQEEN for thoughtful Islamic acrylic reminders and meaningful gifts.'],'/about':['About YAQEEN | A more meaningful life','Discover the story and intention behind YAQEEN and our meaningful Islamic reminders.'],'/contact':['Contact YAQEEN','Get in touch with YAQEEN for product, order or delivery questions.'],'/faq':['Frequently asked questions | YAQEEN','Find answers to common questions about YAQEEN products, orders, payment and delivery.'],'/privacy':['Privacy Policy | YAQEEN','Read how YAQEEN handles information and browser storage when you use the storefront.'],'/terms':['Terms & Conditions | YAQEEN','Read the terms that apply when using the YAQEEN storefront and placing an order.'],'/under-construction':['Coming soon | YAQEEN','Something meaningful is taking shape at YAQEEN. This page will be available soon.']};let [title,description]=labels[path]||[path.startsWith('/products/')?'Islamic acrylic reminder | YAQEEN':'YAQEEN — A more meaningful life','Thoughtful Islamic acrylic reminders for a more meaningful life.'];document.title=title;const canonical=PUBLIC_ORIGIN+PUBLIC_BASE+(path==='/'?'/':path);const set=(selector:string,attr:string,value:string)=>{let el=document.head.querySelector<HTMLMetaElement>(selector);if(!el){el=document.createElement('meta');if(selector.includes('property='))el.setAttribute('property',selector.match(/property="([^"]+)/)?.[1]||'');else el.name=selector.match(/name="([^"]+)/)?.[1]||'';document.head.appendChild(el)}el.setAttribute(attr,value)};set('meta[name="description"]','content',description);const knownCmsPages=new Set(['/about','/contact','/faq']);const singleSegment=/^\/[a-z0-9-]+$/i.test(path);const noindex=path==='/cart'||path==='/checkout'||path==='/order-confirmation'||path==='/search'||path==='/under-construction'||(singleSegment&&!labels[path]&&!knownCmsPages.has(path));set('meta[name="robots"]','content',noindex?'noindex, nofollow':'index, follow');set('meta[property="og:title"]','content',title);set('meta[property="og:description"]','content',description);set('meta[property="og:type"]','content',path.startsWith('/products/')?'product':'website');set('meta[property="og:url"]','content',canonical);set('meta[property="og:site_name"]','content','YAQEEN');set('meta[name="twitter:card"]','content','summary_large_image');set('meta[name="twitter:title"]','content',title);set('meta[name="twitter:description"]','content',description);set('meta[property="og:image"]','content',SOCIAL_SHARE_IMAGE);set('meta[property="og:image:alt"]','content','YAQEEN — A More Meaningful Life');set('meta[name="twitter:image"]','content',SOCIAL_SHARE_IMAGE);set('meta[name="twitter:image:alt"]','content','YAQEEN — A More Meaningful Life');let link=document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]');if(!link){link=document.createElement('link');link.rel='canonical';document.head.appendChild(link)}link.href=canonical},[loc.pathname]);return null}

function Analytics(){const loc=useLocation();const[id,setId]=useState('');const[allowed,setAllowed]=useState(()=>{try{return localStorage.getItem('yaqeen-cookie-consent')==='accepted'}catch{return false}});useEffect(()=>{const onConsent=(event:Event)=>setAllowed((event as CustomEvent<string>).detail==='accepted');window.addEventListener('cookieconsentchange',onConsent);if(supabase)void supabase.from('site_settings').select('value').eq('key','website').maybeSingle().then(({data})=>setId(String(data?.value?.ga_measurement_id||data?.value?.google_analytics_id||'').trim()));return()=>window.removeEventListener('cookieconsentchange',onConsent)},[]);useEffect(()=>{if(!allowed||!/^G-[A-Z0-9]+$/i.test(id))return;const w=window as any;w.dataLayer=w.dataLayer||[];w.gtag=w.gtag||function(){w.dataLayer.push(arguments)};if(!document.querySelector('script[data-yaqeen-ga]')){const script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(id);script.dataset.yaqeenGa='true';document.head.appendChild(script);w.gtag('js',new Date());w.gtag('config',id,{send_page_view:false,anonymize_ip:true})}w.gtag('event','page_view',{page_title:document.title,page_location:window.location.href,page_path:loc.pathname+loc.search})},[allowed,id,loc.pathname,loc.search]);return null}

function SiteFavicon(){useEffect(()=>{let live=true;const apply=(value:string)=>{let link=document.querySelector<HTMLLinkElement>('link[rel="icon"]');if(!value){link?.remove();return}if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.href=value};const onChange=(event:Event)=>apply((event as CustomEvent<string>).detail);window.addEventListener('sitefaviconchange',onChange);if(supabase)void supabase.from('site_settings').select('value').eq('key','website').maybeSingle().then(({data})=>{if(live)apply(data?.value?.favicon_url||'')});return()=>{live=false;window.removeEventListener('sitefaviconchange',onChange)}},[]);return null}
export default function App(){const {pathname}=useLocation();useLayoutEffect(()=>{const {area,screen}=styleScope(pathname);document.documentElement.dataset.styleArea=area;document.documentElement.dataset.styleScreen=screen;return()=>{delete document.documentElement.dataset.styleArea;delete document.documentElement.dataset.styleScreen}},[pathname]);return <><SiteFavicon/><SeoMetadata/><Analytics/><Routes><Route path="/login" element={<Login/>}/><Route path="/admin/*" element={<Admin/>}/><Route path="*" element={<><Header/><main id="main"><Routes><Route path="/" element={<Home/>}/><Route path="/shop" element={<Products/>}/><Route path="/products/:slug" element={<ProductPage/>}/><Route path="/cart" element={<CartPage/>}/><Route path="/checkout" element={<CheckoutPage/>}/><Route path="/order-confirmation" element={<ConfirmationPage/>}/><Route path="/search" element={<SearchPage/>}/><Route path="/privacy" element={<LegalPage kind="privacy"/>}/><Route path="/terms" element={<LegalPage kind="terms"/>}/><Route path="/under-construction" element={<UnderConstruction/>}/><Route path="/:page" element={<ContentPage/>}/><Route path="*" element={<NotFound/>}/></Routes></main><Footer/><CookieConsent/></>}/></Routes></>}
